  const reasonKey = record.event?.name || 'Unknown';
  
  const apportioned = apportionToWeeks(record, weeklyBoundaries, nowMs);
  apportioned.forEach(a => {
    if (weeklyData[a.weekStart]) {
      weeklyData[a.weekStart].repairTimeMs += a.durationMs;
      weeklyData[a.weekStart].unplannedDowntimeMs += a.durationMs;
      
      // Track by reason
      if (!weeklyData[a.weekStart].faultReasons[reasonKey]) {
        weeklyData[a.weekStart].faultReasons[reasonKey] = 0;
      }
      weeklyData[a.weekStart].faultReasons[reasonKey] += a.durationMs;
    }
  });
});
const plannedRecords = extractRecords($.plannedDowntime);

// Process planned downtime
plannedRecords.forEach(record => {
  const apportioned = apportionToWeeks(record, weeklyBoundaries, nowMs);
  apportioned.forEach(a => {
    if (weeklyData[a.weekStart]) {
      weeklyData[a.weekStart].plannedDowntimeMs += a.durationMs;
    }
  });
});


// Build tooltips
const buildUnplannedTooltip = (faultReasons, unplannedMs) => {
  const sorted = Object.entries(faultReasons)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5);
  
  let tooltip = `<b>Unplanned:</b> ${formatDuration(unplannedMs)}`;
  if (sorted.length > 0) {
    tooltip += '<br/><b>Top Reasons:</b>';
    sorted.forEach(([reason, ms]) => {
      tooltip += `<br/>• ${reason}: ${formatDuration(ms)}`;
    });
  }
  return tooltip;
};

const buildPlannedTooltip = (plannedMs) => {
  return `<b>Planned:</b> ${formatDuration(plannedMs)}`;
};

// Convert to sorted array
const allWeeks = Object.keys(weeklyData).sort();
const weeklyMetrics = allWeeks.map(weekStart => {
  const w = weeklyData[weekStart];
  
  const mtbfMs = w.faultCount > 0 ? w.operatingTimeMs / w.faultCount : null;
  const mttrMs = w.faultCount > 0 ? w.repairTimeMs / w.faultCount : null;
  
  return {
    weekStart: w.weekStart,
    weekLabel: w.weekLabel,
    operatingTimeMs: w.operatingTimeMs,
    unplannedTooltip: buildUnplannedTooltip(w.faultReasons, w.unplannedDowntimeMs),
plannedTooltip: buildPlannedTooltip(w.plannedDowntimeMs),
    faultCount: w.faultCount,
    repairTimeMs: w.repairTimeMs,
    faultReasons: w.faultReasons,
   unplannedTooltip: buildUnplannedTooltip(w.faultReasons, w.unplannedDowntimeMs),
plannedTooltip: buildPlannedTooltip(w.plannedDowntimeMs),
    mtbfMs,
    mtbfHours: mtbfMs != null ? msToHours(mtbfMs) : null,
    mtbfFormatted: formatDuration(mtbfMs),
    mttrMs,
    mttrHours: mttrMs != null ? msToHours(mttrMs) : null,
    mttrFormatted: formatDuration(mttrMs),
    mttrOnTarget: mttrMs != null ? mttrMs <= MTTR_TARGET_MS : null,
    unplannedDowntimeMs: w.unplannedDowntimeMs,
    plannedDowntimeMs: w.plannedDowntimeMs,
    totalDowntimeMs: w.unplannedDowntimeMs + w.plannedDowntimeMs
  };
});

// Period calculations
const calcPeriodMetrics = (weeks) => {
  const t = weeks.reduce((acc, w) => ({
    operatingTimeMs: acc.operatingTimeMs + w.operatingTimeMs,
    faultCount: acc.faultCount + w.faultCount,
    repairTimeMs: acc.repairTimeMs + w.repairTimeMs
  }), { operatingTimeMs: 0, faultCount: 0, repairTimeMs: 0 });
  
  const mtbf = t.faultCount > 0 ? t.operatingTimeMs / t.faultCount : 0;
  const mttr = t.faultCount > 0 ? t.repairTimeMs / t.faultCount : 0;
  
  return {
    mtbf,
    mtbfFormatted: formatDuration(mtbf),
    mttr,
    mttrFormatted: formatDuration(mttr),
    faultCount: t.faultCount,
    operatingTimeMs: t.operatingTimeMs,
    operatingTime: formatDuration(t.operatingTimeMs),
    repairTimeMs: t.repairTimeMs,
    repairTime: formatDuration(t.repairTimeMs)
  };
};



const currentWeeks = weeklyMetrics.slice(-4);
const priorWeeks = weeklyMetrics.slice(-8, -4);
const baselineWeeks = weeklyMetrics.slice(-12, -8);

const currentMetrics = calcPeriodMetrics(currentWeeks);
const priorMetrics = calcPeriodMetrics(priorWeeks);
const baselineMetrics = calcPeriodMetrics(baselineWeeks);
const overallMetrics = calcPeriodMetrics(weeklyMetrics);

// Trend calculations
const mtbfChangeVsPrior = (priorMetrics.mtbf > 0 && currentMetrics.mtbf > 0)
  ? (currentMetrics.mtbf - priorMetrics.mtbf) / priorMetrics.mtbf
  : null;

const mttrChangeVsPrior = (priorMetrics.mttr > 0 && currentMetrics.mttr > 0)
  ? (currentMetrics.mttr - priorMetrics.mttr) / priorMetrics.mttr
  : null;

const getMtbfTrend = (change) => {
  if (change == null) return "unknown";
  if (change > 0.1) return "improving";
  if (change < -0.1) return "degrading";
  return "stable";
};

const getMttrTrend = (change) => {
  if (change == null) return "unknown";
  if (change < -0.1) return "improving";
  if (change > 0.1) return "degrading";
  return "stable";
};

const mtbfTrend = getMtbfTrend(mtbfChangeVsPrior);
const mttrTrend = getMttrTrend(mttrChangeVsPrior);

const reliability = {
  current: {
    ...currentMetrics,
    periodLabel: "Last 30 days",
    periodDays: 30
  },
  prior: {
    ...priorMetrics,
    periodLabel: "30-60 days ago",
    periodDays: 30
  },
  baseline: {
    ...baselineMetrics,
    periodLabel: "60-90 days ago",
    periodDays: 30
  },
  overall: {
    ...overallMetrics,
    periodLabel: "Last 90 days",
    periodDays: 90
  },
  trend: {
    mtbfChangeVsPrior,
    mtbfChangeFormatted: formatPctChange(mtbfChangeVsPrior),
    mtbfTrend,
    mttrChangeVsPrior,
    mttrChangeFormatted: formatPctChange(mttrChangeVsPrior),
    mttrTrend
  },
  summary: {
    mtbf: currentMetrics.mtbf,
    mtbfFormatted: currentMetrics.mtbfFormatted,
    mtbfTrendIcon: mtbfTrend === "improving" ? "▲" : mtbfTrend === "degrading" ? "▼" : "→",
    mtbfTrendLabel: formatPctChange(mtbfChangeVsPrior) + " vs prior 30d",
    mttr: currentMetrics.mttr,
    mttrFormatted: currentMetrics.mttrFormatted,
    mttrTrendIcon: mttrTrend === "improving" ? "▼" : mttrTrend === "degrading" ? "▲" : "→",
    mttrTrendLabel: formatPctChange(mttrChangeVsPrior) + " vs prior 30d"
  }
};

// Chart categories
const categories = [{
  category: weeklyMetrics.map(w => ({ label: w.weekLabel }))
}];

// MTBF Trend Chart
const mtbfTrendChart = {
  chart: {
    caption: "MTBF Trend",
    subcaption: "Weekly - Last 12 Weeks",
    xAxisName: "Week",
    yAxisName: "Hours",
    theme: "fusion",
    showValues: "0",
    connectNullData: "1",
    drawCrossLine: "1"
  },
  categories: categories,
  dataset: [
    {
      seriesname: "MTBF",
      color: "#2E86AB",
      data: weeklyMetrics.map(w => ({
        value: w.mtbfHours != null ? w.mtbfHours.toFixed(2) : null
      }))
    }
  ]
};

// MTTR Trend Chart
const mttrTrendChart = {
  chart: {
    caption: "MTTR Trend",
    subcaption: "Weekly - Last 12 Weeks",
    xAxisName: "Week",
    yAxisName: "Hours",
    theme: "fusion",
    showValues: "0",
    connectNullData: "1",
    drawCrossLine: "1"
  },
  categories: categories,
  dataset: [
    {
      seriesname: "MTTR",
      color: "#A23B72",
      data: weeklyMetrics.map(w => ({
        value: w.mttrHours != null ? w.mttrHours.toFixed(2) : null
      }))
    },
    {
      seriesname: "Target",
      renderAs: "line",
      dashed: "1",
      color: "#FF5733",
      showValues: "0",
      data: weeklyMetrics.map(() => ({ value: MTTR_TARGET_HOURS.toFixed(2) }))
    }
  ]
};

// Fault Count Chart
const faultCountChart = {
  chart: {
    caption: "Weekly Fault Count",
    xAxisName: "Week",
    yAxisName: "Faults",
    theme: "fusion",
    showValues: "1"
  },
  data: weeklyMetrics.map(w => ({
    label: w.weekLabel,
    value: w.faultCount
  }))
};

// Downtime Chart
const downtimeChart = {
  chart: {
    caption: "Weekly Downtime",
    xAxisName: "Week",
    yAxisName: "Hours",
    theme: "fusion",
    showValues: "0",
    plotToolText: "$tooltext"
  },
  categories: categories,
dataset: [
  {
    seriesname: "Unplanned",
    color: "#E74C3C",
    data: weeklyMetrics.map(w => ({
      value: msToHours(w.unplannedDowntimeMs).toFixed(2),
      tooltext: w.unplannedTooltip
    }))
  },
  {
    seriesname: "Planned",
    color: "#3498DB",
    data: weeklyMetrics.map(w => ({
      value: msToHours(w.plannedDowntimeMs).toFixed(2),
      tooltext: w.plannedTooltip
    }))
  }
]};

// MTBF Bullet Chart
const mtbfUpperLimit = Math.max(
  msToHours(currentMetrics.mtbf) || 0,
  msToHours(priorMetrics.mtbf) || 0,
  msToHours(baselineMetrics.mtbf) || 0,
  1
) * 1.2;

const mtbfBulletChart = {
  chart: {
    caption: "MTBF",
    subcaption: "Current vs Prior Periods",
    lowerLimit: "0",
    upperLimit: safeToFixed(mtbfUpperLimit),
    numberSuffix: " hrs",
    theme: "fusion"
  },
  colorRange: {
    color: [
      { minValue: "0", maxValue: safeToFixed(mtbfUpperLimit * 0.33), code: "#F2726F", label: "Poor" },
      { minValue: safeToFixed(mtbfUpperLimit * 0.33), maxValue: safeToFixed(mtbfUpperLimit * 0.67), code: "#FFC533", label: "Average" },
      { minValue: safeToFixed(mtbfUpperLimit * 0.67), maxValue: safeToFixed(mtbfUpperLimit), code: "#62B58F", label: "Good" }
    ]
  },
  value: safeToFixed(msToHours(currentMetrics.mtbf)),
  target: safeToFixed(msToHours(priorMetrics.mtbf))
};

// MTTR Bullet Chart
const mttrUpperLimit = Math.max(
  msToHours(currentMetrics.mttr) || 0,
  msToHours(priorMetrics.mttr) || 0,
  MTTR_TARGET_HOURS,
  1
) * 1.2;

const mttrBulletChart = {
  chart: {
    caption: "MTTR",
    subcaption: "Current vs Target",
    lowerLimit: "0",
    upperLimit: safeToFixed(mttrUpperLimit),
    numberSuffix: " hrs",
    theme: "fusion"
  },
  colorRange: {
    color: [
      { minValue: "0", maxValue: safeToFixed(MTTR_TARGET_HOURS), code: "#62B58F", label: "On Target" },
      { minValue: safeToFixed(MTTR_TARGET_HOURS), maxValue: safeToFixed(MTTR_TARGET_HOURS * 1.5), code: "#FFC533", label: "Warning" },
      { minValue: safeToFixed(MTTR_TARGET_HOURS * 1.5), maxValue: safeToFixed(mttrUpperLimit), code: "#F2726F", label: "Critical" }
    ]
  },
  value: safeToFixed(msToHours(currentMetrics.mttr)),
  target: safeToFixed(MTTR_TARGET_HOURS)
};

return {
  workcenter: {
    id: $state.context.boundary?.workcenter?.id,
    code: $state.context.boundary?.workcenter?.code,
    name: $state.context.boundary?.workcenter?.name
  },
  lastRefresh: $state.context.boundary?.boundaries?.now,
  lastRefreshFormatted: $moment($state.context.boundary?.boundaries?.now).format('MMM D, YYYY h:mm A'),
  reliability,
  weeklyMetrics,
charts: {
  mtbfTrend: mtbfTrendChart,
  mttrTrend: mttrTrendChart,
  faultCount: faultCountChart,
  downtime: downtimeChart,
  mtbfBullet: mtbfBulletChart,
  mttrBullet: mttrBulletChart
},
  config: {
    mttrTargetMs: MTTR_TARGET_MS,
    mttrTargetHours: MTTR_TARGET_HOURS,
    weekCount: weeklyMetrics.length
  }
};
